import{_ as t,o as i,c as a,aa as n}from"./chunks/framework.BAs_AphD.js";const s="/buildary-help-preview/media/en/tickets/en_ciselniky_mu.png",r="/buildary-help-preview/media/en/tickets/en_kategorie_ukolu2.png",o="/buildary-help-preview/media/en/tickets/en_btn_pridat.png",l="/buildary-help-preview/media/en/tickets/en_pravidla2.png",d="/buildary-help-preview/media/en/tickets/en_nove_pravidlo.png",c="/buildary-help-preview/media/en/tickets/en_nove_pravidlo2.png",g="/buildary-help-preview/media/en/tickets/en_stitky2.png",w=JSON.parse('{"title":"Code Lists – Ticket Management","description":"","frontmatter":{"title":"Code Lists – Ticket Management","wiki":"en:tickets:rules"},"headers":[],"relativePath":"en/tickets/rules.md","filePath":"en/tickets/rules.md","lastUpdated":1794388980000}'),p={name:"en/tickets/rules.md"};function h(u,e,m,b,f,y){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="code-lists-–-ticket-management" tabindex="-1">Code Lists – Ticket Management <a class="header-anchor" href="#code-lists-–-ticket-management" aria-label="Permalink to &quot;Code Lists – Ticket Management&quot;">​</a></h1><figure class="shot" style="--w:520px;"><img src="'+s+'" alt="Code List – Ticket Management" width="500" loading="lazy"></figure><p>This section of the project settings contains all code lists available in the Ticket Management module that can be defined or modified by the project administrator.</p><p>These include:</p><ul><li>Ticket Categories</li><li>Assignees Rule</li><li>Approvers Rule</li><li>Labels</li></ul><h2 id="ticket-categories" tabindex="-1">Ticket Categories <a class="header-anchor" href="#ticket-categories" aria-label="Permalink to &quot;Ticket Categories&quot;">​</a></h2><figure class="shot" style="--w:570px;"><img src="'+r+'" alt="Ticket Categories" width="550" loading="lazy"></figure><p><strong>Ticket Categories</strong> is a code list used to divide tickets into basic groups according to the subject matter they concern. This code list is predefined by default, and users select an item when creating a new ticket or editing an existing one.</p><p>The administrator can modify or delete the predefined items using the icons at the end of each row, or add new ones using the <img src="'+o+'" alt="+ Add" data-no-zoom loading="lazy"> button.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Categories that are already used in a ticket cannot be deleted. They can only be edited.</p></div><p>The <strong>two-letter abbreviation</strong> is used to make it easier to identify locations where the category is represented by an icon containing this abbreviation. We therefore recommend choosing an intuitive abbreviation.</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><figure class="shot" style="--w:600px;"><img src="'+l+'" alt="Rules" width="580" loading="lazy"></figure><p>A <strong>Rule</strong> is a set of conditions under which the <strong>Assignees</strong> and/or <strong>Approvers</strong> field is automatically populated when a ticket is created.</p><p>A user with administrator rights can create different rules for different situations where the responsible persons are clearly defined.</p><p>This can save a significant amount of time and effort and eliminate uncertainty when creating new tickets.</p><p>Rules can be added gradually, and there is no limit to the number of rules that can be defined.</p><p>Their <strong>order can be changed in the list</strong> according to their importance or priority (a rule higher in the list takes precedence over a rule below it).</p><figure class="shot" style="--w:300px;"><img src="'+d+'" alt="New Rule" width="280" loading="lazy"></figure><figure class="shot" style="--w:300px;"><img src="'+c+'" alt="Rule Definition" width="280" loading="lazy"></figure><p>A <strong>New Rule</strong> is defined by selecting <strong>one or more persons in the Assignees or Approvers field</strong>, depending on which tab the rule is being created in. Persons are selected from a list containing all Project Team Members. If the required person is not listed, they must first be added to the project&#39;s Project Team.</p><p><strong>The rule conditions are defined by selecting:</strong></p><ul><li><strong>Category</strong> - the list of categories is defined in the adjacent tab</li><li><strong>Project Parts</strong> - the list is based on the Project Parts and Drawings tab, which must first be defined by the administrator</li><li><strong>Drawings</strong> - drawings must be uploaded in the Project Parts and Drawings tab before they can be selected</li></ul><p><strong>Example</strong></p><p>The image on the right shows the following rule: If a ticket is assigned to the category Construction work, OR Project preparation, AND at the same time concerns any floor on Project Part SO 01 , the <strong>Assignees</strong> field will be automatically populated with the names Jan Buildary and Milan Holkovič. These names can then be individually supplemented with additional people or changed directly in the ticket.</p><p>If the ticket concerned Project Part SO 01 but had, for example, the category Inspections and Tests, the condition would not be met and the rule would not be applied.</p><h2 id="labels" tabindex="-1">Labels <a class="header-anchor" href="#labels" aria-label="Permalink to &quot;Labels&quot;">​</a></h2><figure class="shot" style="--w:520px;"><img src="'+g+'" alt="Labels" width="500" loading="lazy"></figure><p>Tickets can be organized not only by assigning them to a category, but also according to individual parameters by adding a label.</p><p>This code list is empty by default, and the administrator can define labels according to the specific characteristics and requirements of the project.</p><p><strong>For each label, a color, name, and optionally a description can be specified.</strong> Color highlighting makes it easier to identify and visually categorize tickets at a glance.</p><p><strong>Labels</strong> are displayed <strong>in the ticket list</strong> (after adding the relevant column to the view), and tickets can be <strong>filtered</strong> by them.</p><p>In the Ticket Kanban, labels are displayed automatically, but tickets cannot be filtered by them.</p>',33)])])}const _=t(p,[["render",h]]);export{w as __pageData,_ as default};
